create table public.national_rule_sets (id uuid primary key default gen_random_uuid(), name text not null, effective_from date not null, effective_to date, source_label text not null, status text not null default 'active', created_at timestamptz not null default now());
create table public.national_assessment_rules (id uuid primary key default gen_random_uuid(), rule_set_id uuid not null references public.national_rule_sets(id) on delete cascade, grade_level_id uuid references public.grade_levels(id), assessment_domain public.assessment_domain not null, duration_minutes integer not null, total_points numeric(5,2) not null, distribution jsonb not null, bloom_lower_ratio numeric(3,2) not null default 0.60, bloom_upper_ratio numeric(3,2) not null default 0.40, created_at timestamptz not null default now());
create table public.assessment_coverage_snapshots (id uuid primary key default gen_random_uuid(), assessment_id uuid not null references public.summative_assessments(id) on delete cascade, rule_set_id uuid references public.national_rule_sets(id), coverage jsonb not null, created_at timestamptz not null default now());
create table public.assessment_item_mappings (id uuid primary key default gen_random_uuid(), assessment_item_id uuid not null references public.summative_assessment_items(id) on delete cascade, plan_item_id uuid references public.plan_items(id), curriculum_segment_id uuid references public.curriculum_segments(id), competence text, created_at timestamptz not null default now());
alter table public.national_rule_sets enable row level security;alter table public.national_assessment_rules enable row level security;alter table public.assessment_coverage_snapshots enable row level security;alter table public.assessment_item_mappings enable row level security;
create policy "read national rules" on public.national_rule_sets for select to authenticated using(true);create policy "read national assessment rules" on public.national_assessment_rules for select to authenticated using(true);create policy "workspace read coverage" on public.assessment_coverage_snapshots for select to authenticated using(exists(select 1 from public.summative_assessments a where a.id=assessment_id and public.is_active_member(a.organization_id)));create policy "workspace read mappings" on public.assessment_item_mappings for select to authenticated using(exists(select 1 from public.summative_assessment_items i join public.summative_assessments a on a.id=i.assessment_id where i.id=assessment_item_id and public.is_active_member(a.organization_id)));
